import{_ as o,o as d,c as i,a5 as a}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"Technical Implementation Plan — Skill-Driven Multi-Model Studio Image Pipeline (skill-driven-multi-model-studio-image)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/06-ai-media-and-video-studio/skill-driven-multi-model-studio-image/plan.md","filePath":"feature/modules/06-ai-media-and-video-studio/skill-driven-multi-model-studio-image/plan.md"}'),t={name:"feature/modules/06-ai-media-and-video-studio/skill-driven-multi-model-studio-image/plan.md"};function c(s,e,r,n,l,p){return d(),i("div",null,[...e[0]||(e[0]=[a(`<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <a href="./spec.html">Spec</a> · <strong>Plan</strong> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="technical-implementation-plan-—-skill-driven-multi-model-studio-image-pipeline-skill-driven-multi-model-studio-image" tabindex="-1">Technical Implementation Plan — Skill-Driven Multi-Model Studio Image Pipeline (<code>skill-driven-multi-model-studio-image</code>) <a class="header-anchor" href="#technical-implementation-plan-—-skill-driven-multi-model-studio-image-pipeline-skill-driven-multi-model-studio-image" aria-label="Permalink to &quot;Technical Implementation Plan — Skill-Driven Multi-Model Studio Image Pipeline (\`skill-driven-multi-model-studio-image\`)&quot;">​</a></h1><h2 id="_1-system-components-touched-repositories" tabindex="-1">1. System Components &amp; Touched Repositories <a class="header-anchor" href="#_1-system-components-touched-repositories" aria-label="Permalink to &quot;1. System Components &amp; Touched Repositories&quot;">​</a></h2><p>Implements <a href="./spec.html">spec.md</a> across four repositories while preserving full compatibility with existing Vast.ai Qwen workflows:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Layer / Repository</th><th style="text-align:left;">Key Files, Services &amp; Components</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Skills Library (<code>brandhub-ai-service/.agents/skills/</code>)</strong></td><td style="text-align:left;"><code>agency-creative-director/</code> (<code>SKILL.md</code> + <code>references/</code>), <code>product-posing/</code>, <code>virtual-try-on/</code>, <code>outfit-replacement/</code>, <code>pose-director/</code>, <code>product-photography/</code>, <code>background-replacement/</code>, <code>advertising-key-visual/</code>, <code>commercial-retouching/</code>, <code>brand-consistency/</code> (<code>SKILL.md</code>)</td></tr><tr><td style="text-align:left;"><strong>AI Service (<code>brandhub-ai-service</code>)</strong></td><td style="text-align:left;"><code>app/core/config.py</code>, <code>.env.example</code>, <code>app/schemas/studio_image.py</code>, <code>app/services/image/skill_loader.py</code>, <code>app/services/image/agy_provider.py</code>, <code>app/services/image/codex_provider.py</code>, <code>app/services/image/storage_service.py</code>, <code>app/services/qwen_ambassador_client.py</code>, <code>app/api/v2/endpoints/studio_image.py</code>, <code>app/main.py</code>, <code>Dockerfile</code>, <code>docker/{docker-entrypoint.sh,agy-login.sh}</code></td></tr><tr><td style="text-align:left;"><strong>Business Service (<code>brandhub-business-service</code>)</strong></td><td style="text-align:left;"><code>AiGenerationController.java</code>, <code>AiCreditGenerationService.java</code>, <code>AiServiceClient.java</code> (forward <code>models</code>, <code>studio/generate</code>, <code>studio/generate/stream</code>, <code>pose-match</code>, <code>virtual-try-on</code> with credit reserve/settle)</td></tr><tr><td style="text-align:left;"><strong>Web Frontend (<code>brandhub-web</code>)</strong></td><td style="text-align:left;"><code>src/pages/studio/types/studio.ts</code>, <code>src/pages/studio/components/nodes/StudioNodeInspectorDock.tsx</code>, <code>src/pages/studio/components/nodes/StudioNodes.tsx</code>, <code>src/pages/studio/components/StudioSimpleMode.tsx</code>, <code>src/pages/studio/components/KSamplerOutputPreview.tsx</code>, <code>src/pages/studio/services/studioAiRunner.ts</code>, <code>src/services/aiGenerationService.ts</code>, <code>src/i18n/locales/{vi,en}/aiStudio.json</code></td></tr><tr><td style="text-align:left;"><strong>Prod Infra (<code>brandhub-infrastructure</code>)</strong></td><td style="text-align:left;"><code>prod/hosts/ai/ai.compose.json</code> (persistent <code>.gemini</code> &amp; keyring Docker volumes; <code>AGY_MODEL</code>, <code>AGY_IMG</code>, <code>GPT_MODEL</code>, <code>GPT_IMG_FAST</code>, <code>GPT_IMG_NOR</code> env wiring)</td></tr></tbody></table><hr><h2 id="_2-core-technical-design-module-responsibilities" tabindex="-1">2. Core Technical Design &amp; Module Responsibilities <a class="header-anchor" href="#_2-core-technical-design-module-responsibilities" aria-label="Permalink to &quot;2. Core Technical Design &amp; Module Responsibilities&quot;">​</a></h2><h3 id="_2-1-zero-turn-skill-injection-app-services-image-skill-loader-py" tabindex="-1">2.1 Zero-Turn Skill Injection (<code>app/services/image/skill_loader.py</code>) <a class="header-anchor" href="#_2-1-zero-turn-skill-injection-app-services-image-skill-loader-py" aria-label="Permalink to &quot;2.1 Zero-Turn Skill Injection (\`app/services/image/skill_loader.py\`)&quot;">​</a></h3><ul><li>Reads <code>agency-creative-director/SKILL.md</code> + the matched task <code>SKILL.md</code> files once at startup (cached in memory via <code>@lru_cache</code>).</li><li>Maps <code>workflow_mode</code> (<code>ad-composer</code>, <code>pose-match</code>, <code>virtual-tryon</code>, <code>refine</code>, <code>ambassador</code>, <code>product</code>, <code>key-visual</code>, <code>background</code>) + optional <code>brand_context</code> into a compact, deterministic Creative Director system directive (<code>&lt;= 1,800</code> tokens).</li><li>Ensures <strong>zero</strong> extra CLI tool calls for reading skill markdown files during live requests.</li></ul><h3 id="_2-2-antigravity-cli-provider-app-services-image-agy-provider-py" tabindex="-1">2.2 Antigravity CLI Provider (<code>app/services/image/agy_provider.py</code>) <a class="header-anchor" href="#_2-2-antigravity-cli-provider-app-services-image-agy-provider-py" aria-label="Permalink to &quot;2.2 Antigravity CLI Provider (\`app/services/image/agy_provider.py\`)&quot;">​</a></h3><ul><li><strong>Cross-platform binary resolution</strong>: <code>AGY_CLI_PATH</code> → Windows <code>%LOCALAPPDATA%\\agy\\bin\\agy.exe</code> → Linux <code>~/.local/bin/agy</code> → <code>shutil.which(&quot;agy&quot;)</code>.</li><li><strong>Effort &amp; Model routing</strong>: <ul><li><code>effort == &quot;low&quot;</code> → runs <code>AGY_IMG</code> (<code>gemini-3.8-flash-low</code>) with direct skill-synthesized brief (~29–39s).</li><li><code>effort in (&quot;medium&quot;, &quot;high&quot;)</code> → runs <code>AGY_MODEL</code> (<code>gemini-4-neon-low</code>) as Creative Director orchestrator + <code>image-generator</code> (~45–65s).</li></ul></li><li><strong>Streaming &amp; Early Capture</strong>: Uses <code>subprocess.Popen</code> + threaded <code>asyncio.Queue</code> (works identically on Windows <code>SelectorEventLoop</code> and Linux <code>epoll</code>), parses <code>stream-json</code> + tails <code>&lt;brain&gt;/&lt;subagent_conv_id&gt;/transcript.jsonl</code> to emit real <code>orchestrating</code> → <code>composing</code> → <code>sampling</code> (with <code>expanded_prompt</code>) → <code>storing</code> → <code>completed</code> events, verifies JPEG EOI (<code>\\xff\\xd9</code>) + <code>PIL.Image.verify()</code>, and deletes both <code>&lt;parent_conv_id&gt;</code> and <code>&lt;subagent_conv_id&gt;</code> directories in <code>finally</code>.</li><li><strong>Memory &amp; Concurrency Guard</strong>: Protected by <code>asyncio.Semaphore(settings.agy_max_concurrency)</code> (default <code>1</code> inside the <code>3g</code> <code>brandhub-ai</code> container).</li></ul><h3 id="_2-3-codex-oauth-image-provider-app-services-image-codex-provider-py" tabindex="-1">2.3 Codex OAuth Image Provider (<code>app/services/image/codex_provider.py</code>) <a class="header-anchor" href="#_2-3-codex-oauth-image-provider-app-services-image-codex-provider-py" aria-label="Permalink to &quot;2.3 Codex OAuth Image Provider (\`app/services/image/codex_provider.py\`)&quot;">​</a></h3><ul><li>Reads <code>CODEX_OAUTH_ACCESS_TOKEN</code> (env or <code>CODEX_AUTH_JSON_PATH</code> / <code>~/.codex/auth.json</code>) and extracts <code>ChatGPT-Account-Id</code> from the JWT <code>https://api.openai.com/auth</code> claim.</li><li><strong>Model &amp; Effort mapping</strong>: <ul><li>Orchestrator <code>model</code>: strips <code>-light</code> suffix from <code>GPT_MODEL=gpt-6-sol-light</code> → sends <code>&quot;model&quot;: &quot;gpt-6-sol&quot;</code> with <code>&quot;reasoning&quot;: {&quot;effort&quot;: effort}</code> (<code>low</code> / <code>medium</code> / <code>high</code>).</li><li>Image tool <code>model</code>: <code>gpt-image-2.6-flare</code> (<code>GPT_IMG_FAST</code>) or <code>gpt-image-2.6-sunburst</code> (<code>GPT_IMG_NOR</code>), with <code>partial_images: 3</code> so SSE emits real <code>response.image_generation_call.partial_image</code> (<code>preview_image</code>) frames!</li></ul></li><li><strong>Reference Images</strong>: Encodes up to 3 reference images (<code>model</code>, <code>product</code>, <code>pose</code>/<code>outfit</code>) as <code>input_image</code> parts in <code>input[0].content</code>.</li></ul><h3 id="_2-4-qwen-worker-completion-qwen-ambassador-client-py-studio-image-py" tabindex="-1">2.4 Qwen Worker Completion (<code>qwen_ambassador_client.py</code> + <code>studio_image.py</code>) <a class="header-anchor" href="#_2-4-qwen-worker-completion-qwen-ambassador-client-py-studio-image-py" aria-label="Permalink to &quot;2.4 Qwen Worker Completion (\`qwen_ambassador_client.py\` + \`studio_image.py\`)&quot;">​</a></h3><ul><li>Adds <code>pose_match(prompt, image1_bytes, image2_bytes, ...)</code> calling <code>/api/v1/wf2/pose_match</code> on Vast.ai worker.</li><li>Adds <code>virtual_try_on(prompt, image1_bytes, image2_bytes, ...)</code> calling <code>/api/v1/wf3/outfit_change</code> on Vast.ai worker.</li><li>Preserves existing <code>/api/v1/ai/ambassadors/*</code> and <code>/api/v2/ai/image/commercial/generate</code> routes intact.</li></ul><h3 id="_2-5-hybrid-s3-local-storage-app-services-image-storage-service-py" tabindex="-1">2.5 Hybrid S3 / Local Storage (<code>app/services/image/storage_service.py</code>) <a class="header-anchor" href="#_2-5-hybrid-s3-local-storage-app-services-image-storage-service-py" aria-label="Permalink to &quot;2.5 Hybrid S3 / Local Storage (\`app/services/image/storage_service.py\`)&quot;">​</a></h3><ul><li>Enhances <code>is_s3_configured()</code> so when <code>STORAGE_BACKEND</code> is <code>&quot;s3&quot;</code> (or <code>&quot;auto&quot;</code> with <code>S3_BUCKET_NAME</code>), it checks explicit AWS keys <strong>or</strong> <code>boto3.Session().get_credentials() is not None</code> (supporting EC2 IMDSv2 Instance Role <code>brandhub-ec2-ecr-pull</code> on <code>brandhub-ai</code> without static keys).</li><li>Falls back cleanly to <code>/static/generated/{id}.png</code> in local development when S3 is unconfigured.</li></ul><hr><h2 id="_3-end-to-end-data-ksampler-streaming-flow" tabindex="-1">3. End-to-End Data &amp; KSampler Streaming Flow <a class="header-anchor" href="#_3-end-to-end-data-ksampler-streaming-flow" aria-label="Permalink to &quot;3. End-to-End Data &amp; KSampler Streaming Flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>brandhub-web (Studio Node: model + effort)</span></span>
<span class="line"><span>  │  POST /api/v1/ai/image/studio/generate/stream (or /generate)</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>brandhub-api-gateway (:8080, proxy_buffering off, 1260s timeout)</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>brandhub-business-service (:8081, AiCreditGenerationService: reserve 1 credit)</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>brandhub-ai-service (:8082, studio_image.py)</span></span>
<span class="line"><span>  ├── skill_loader.py: load agency-creative-director + matched task SKILL.md + brand_context</span></span>
<span class="line"><span>  ├── model == &quot;qwen-studio&quot; ──► QwenAmbassadorClient (wf1 / wf2 / wf3 / ambassador)</span></span>
<span class="line"><span>  ├── model == &quot;agy&quot; ──────────► agy_provider.py (Semaphore(1) -&gt; stream-json -&gt; early JPEG)</span></span>
<span class="line"><span>  └── model == &quot;gpt-image-2.6-*&quot; ► codex_provider.py (gpt-6-sol + partial_image_b64 stream)</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>storage_service.py (Prod S3 brandhub-media OR Local /static/generated)</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>KSamplerOutputPreview.tsx (renders live steps, expanded prompt, partial/denoise frames, final image)</span></span></code></pre></div><hr><h2 id="_4-sequential-implementation-rollout-order" tabindex="-1">4. Sequential Implementation &amp; Rollout Order <a class="header-anchor" href="#_4-sequential-implementation-rollout-order" aria-label="Permalink to &quot;4. Sequential Implementation &amp; Rollout Order&quot;">​</a></h2><ol><li><strong>Phase 1 — Skills &amp; Config Baseline:</strong> Author the 10 <code>SKILL.md</code> files under <code>brandhub-ai-service/.agents/skills/</code>, update <code>app/core/config.py</code> and <code>.env.example</code>, and fix <code>is_s3_configured()</code> in <code>storage_service.py</code> for EC2 IMDSv2.</li><li><strong>Phase 2 — Providers &amp; Qwen <code>wf2</code>/<code>wf3</code>:</strong> Implement <code>skill_loader.py</code>, <code>agy_provider.py</code>, <code>codex_provider.py</code>, and add <code>pose_match</code> / <code>virtual_try_on</code> to <code>qwen_ambassador_client.py</code>.</li><li><strong>Phase 3 — FastAPI &amp; Business Service Contracts:</strong> Add <code>studio_image.py</code> (<code>GET /models</code>, <code>POST /generate</code>, <code>POST /generate/stream</code>, <code>POST /pose-match</code>, <code>POST /virtual-try-on</code>) and wire <code>AiGenerationController.java</code> + <code>AiCreditGenerationService.java</code> with credit reserve/settle and SSE passthrough.</li><li><strong>Phase 4 — Studio Web UI &amp; KSampler Preview:</strong> Extend <code>studio.ts</code>, <code>StudioNodeInspectorDock.tsx</code>, <code>StudioNodes.tsx</code>, <code>StudioSimpleMode.tsx</code>, <code>KSamplerOutputPreview.tsx</code>, <code>studioAiRunner.ts</code>, and <code>aiGenerationService.ts</code>.</li><li><strong>Phase 5 — Key-Parallel i18n (<code>vi</code>/<code>en</code>) &amp; Light/Dark Audit:</strong> Add all <code>aiStudio.studio.models.*</code>, <code>effort.*</code>, and <code>ksampler.*</code> keys in <code>vi/aiStudio.json</code> &amp; <code>en/aiStudio.json</code> and verify Light/Dark contrast.</li><li><strong>Phase 6 — Prod Container &amp; Verification:</strong> Update <code>brandhub-ai-service/Dockerfile</code> (<code>dbus-x11</code>, <code>gnome-keyring</code>, <code>agy</code>, <code>agy-login</code>) + <code>brandhub-infrastructure/prod/hosts/ai/ai.compose.json</code> (persistent <code>.gemini</code> + keyring volumes), then run automated tests in <a href="./test.html">test.md</a>.</li></ol><hr><h2 id="_5-localization-theme-tokens-production-risks" tabindex="-1">5. Localization, Theme Tokens &amp; Production Risks <a class="header-anchor" href="#_5-localization-theme-tokens-production-risks" aria-label="Permalink to &quot;5. Localization, Theme Tokens &amp; Production Risks&quot;">​</a></h2><ul><li><strong>i18n Parity:</strong> <code>vi/aiStudio.json</code> and <code>en/aiStudio.json</code> updated in the same commit with zero hardcoded UI strings.</li><li><strong>Light/Dark Mode:</strong> <code>KSamplerOutputPreview.tsx</code> and inspector dropdowns use semantic Tailwind classes (<code>bg-card</code>, <code>bg-muted/40</code>, <code>text-foreground</code>, <code>border-border</code>, <code>text-brand-orange</code>) + <code>dark:</code> variants.</li><li><strong>Risks &amp; Mitigations:</strong><ul><li><em>RAM <code>3g</code> limit on <code>brandhub-ai</code> EC2</em>: <code>asyncio.Semaphore(1)</code> caps concurrent <code>agy</code> runs; <code>codex</code> runs over async <code>httpx</code> with minimal RAM overhead.</li><li><em>Expired Codex OAuth / <code>agy</code> session</em>: Returns <code>502</code>/<code>503</code> without settling the held AI credit (<code>AiCreditGenerationService</code> releases reservation cleanly).</li><li><em>Nginx SSE buffering</em>: <code>X-Accel-Buffering: no</code> header + existing <code>proxy_buffering off</code> in <code>nginx.conf</code> ensures real-time KSampler steps reach the browser immediately.</li></ul></li></ul>`,26)])])}const g=o(t,[["render",c]]);export{u as __pageData,g as default};
